"""Geometry measurement: prints each line with index and marks dialog bounds."""
import sys, os, time, re
sys.path.insert(0, "/workspace/explore")
from tj import Tj

def geom(cap):
    lines = cap.split("\n")
    out = []
    for i, l in enumerate(lines):
        out.append(f"{i:3d}|{l}")
    return "\n".join(out)

def box_bounds(cap, marker):
    """find row/col of a char in a line containing marker"""
    lines = cap.split("\n")
    for i, l in enumerate(lines):
        if marker in l:
            c = l.index(marker)
            return i, c, len(l)
    return None

