#!/usr/bin/env python3
import sys, time
sys.path.insert(0, "/workspace/explore")
from tj import Tj

def bounds(cap, title):
    lines = cap.split("\n")
    top=left=right=None
    for i, l in enumerate(lines):
        if title in l:
            ti = l.index(title); c = l.rindex("┌",0,ti); e = l.index("┐",ti)
            top,left,right = i,c,e; break
    if top is None: return None
    bot=None
    for i in range(top+1,len(lines)):
        if len(lines[i])>left and lines[i][left]=="└":
            bot=i; break
    return (top,bot,left,right,right-left+1,(bot-top+1) if bot else None)

W=int(sys.argv[1]) if len(sys.argv)>1 else 120
rows=range(int(sys.argv[2]),int(sys.argv[3])+1)
for r in rows:
    sess=f"v{W}x{r}"
    t=Tj(home=f"/tmp/h_v_{W}x{r}",cols=W,rows=r,sess=sess)
    t.send("n")
    b=bounds(t.cap(),"Create journal")
    if b:
        top,bot,left,right,w,h=b
        print(f"rows={r:3d} area={r-1:3d} top={top:3d} bot={bot:3d} h={h:3d} left={left:3d} w={w:3d} above={top} below={(r-1)-1-bot}")
    else:
        print(f"rows={r:3d} NOT SHOWN")
    t.kill()

#!/usr/bin/env python3
"""Dump a capE screen as per-row style runs, restricted to rows/cols of interest."""
import sys, re
sys.path.insert(0, "/workspace/explore")
from sgr import parse_line

def runs(capE, r0=0, r1=None, c0=0, c1=None, skip_plain=False):
    out = []
    rows = capE.split("\n")
    if r1 is None: r1 = len(rows)-1
    for y in range(r0, min(r1+1, len(rows))):
        cells = parse_line(rows[y])
        cc1 = len(cells)-1 if c1 is None else min(c1, len(cells)-1)
        segs = []
        cur = None
        for x in range(c0, cc1+1):
            ch, fg, bg, bold = cells[x]
            key = (fg, bg, bold)
            if cur is None or cur[0] != key:
                if cur: segs.append(cur)
                cur = [key, x, ch]
            else:
                cur[2] += ch
        if cur: segs.append(cur)
        desc = []
        for key, x, txt in segs:
            fg, bg, bold = key
            st = []
            if fg: st.append("fg=" + fg)
            if bg: st.append("bg=" + bg)
            if bold: st.append("bold")
            s = ",".join(st) or "-"
            if skip_plain and s == "-":
                continue
            # compress long runs of the same char
            t = txt
            if len(set(t)) == 1 and len(t) > 6:
                t = f"{t[0]!r}x{len(t)}"
            else:
                t = repr(t)
            desc.append(f"[x{x}:{s}]{t}")
        out.append(f"{y:3d} " + " ".join(desc))
    return "\n".join(out)

if __name__ == "__main__":
    data = sys.stdin.read()
    a = [int(x) for x in sys.argv[1:5]] if len(sys.argv) >= 5 else [0, None, 0, None]
    r0 = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    r1 = int(sys.argv[2]) if len(sys.argv) > 2 else None
    c0 = int(sys.argv[3]) if len(sys.argv) > 3 else 0
    c1 = int(sys.argv[4]) if len(sys.argv) > 4 else None
    print(runs(data, r0, r1, c0, c1))
